    for row in ws.iter_rows(min_row=1, max_row=10, max_col=10):
        for cell in row:
            if cell.value and isinstance(cell.value, str) and cell.value.startswith('='):
                print(f'  Formula at {cell.coordinate}: {cell.value}')
