python3 << 'EOF'
import openpyxl
wb = openpyxl.load_workbook('/root/test-supply.xlsx', data_only=False)
ws = wb['PWT']
print('PWT sheet max column:', ws.max_column)
print('PWT sheet max row:', ws.max_row)
print('\nAll cells in PWT sheet:')
for row in ws.iter_rows(min_row=1, max_row=5, max_col=5):
    for cell in row:
        print(f'{cell.coordinate}: value={cell.value}, type={type(cell.value)}')

# Check if there are any comments or notes in the cells
for row in ws.iter_rows(min_row=1, max_row=5, max_col=5):
    for cell in row:
        if cell.comment:
            print(f'{cell.coordinate} has comment: {cell.comment.text}')
